class NASOptimizer:
    """BOA-NAS: Bayesian Optimization with Marginal Model and Local Search.

    Novel contributions:
    1. Marginal probability model per edge/operation with UCB scoring
    2. Adaptive temperature schedule for exploration-exploitation tradeoff
    3. Diversity-aware sampling to prevent premature convergence
    4. Periodic hill-climbing refinement around best architectures
    5. Multi-phase search strategy adapting to available budget
    """

    def __init__(self, api, num_epochs, seed):
        self.api = api
        self.num_epochs = num_epochs
        self.seed = seed

        random.seed(seed)
        np.random.seed(seed)

        self.best_arch = None
        self.best_val_acc = -1.0

        # Marginal model: per-edge operation statistics
        self.edge_op_counts = np.zeros((NUM_EDGES, NUM_OPS))
        self.edge_op_rewards = np.zeros((NUM_EDGES, NUM_OPS))
        self.edge_op_max_reward = np.zeros((NUM_EDGES, NUM_OPS))

        # Observation cache
        self.observed = {}  # arch_tuple -> val_acc
        self.obs_list = []  # list of (arch_tuple, val_acc)

        # Search parameters
        self.temperature = 5.0
        self.temperature_min = 0.05
        self.ucb_weight = 1.0

    def _get_sampling_probs(self):
        """Compute per-edge operation probabilities from marginal model."""
        if not self.obs_list:
            return np.ones((NUM_EDGES, NUM_OPS)) / NUM_OPS

        counts = self.edge_op_counts + 1e-6
        avg_reward = self.edge_op_rewards / counts
        uncertainty = np.sqrt(np.log(max(len(self.obs_list) + 1, 2)) / counts)

        ucb = avg_reward + self.ucb_weight * uncertainty

        for edge in range(NUM_EDGES):
            scaled = ucb[edge] / self.temperature
            scaled = scaled - np.max(scaled)
            probs = np.exp(scaled)
            probs /= probs.sum()
            ucb[edge] = probs

        return ucb

    def _sample_from_model(self):
        """Sample architecture from marginal model."""
        probs = self._get_sampling_probs()
        max_attempts = 30
        for _ in range(max_attempts):
            arch = []
            for edge in range(NUM_EDGES):
                op = int(np.random.choice(NUM_OPS, p=probs[edge]))
                arch.append(op)
            if is_valid_arch(arch) and tuple(arch) not in self.observed:
                return arch
        return None

    def _diverse_sample(self, n_candidates=60):
        """Sample diverse architectures not yet evaluated."""
        candidates = []
        for _ in range(n_candidates):
            arch = random_architecture()
            if tuple(arch) not in self.observed:
                candidates.append(arch)

        if not candidates:
            return random_architecture()

        best_arch = candidates[0]
        best_score = -np.inf

        for arch in candidates:
            score = 0.0
            for edge, op in enumerate(arch):
                cnt = self.edge_op_counts[edge, op]
                if cnt > 0:
                    score += self.edge_op_rewards[edge, op] / cnt
                else:
                    score += 50.0
            # Diversity bonus
            min_dist = NUM_EDGES
            for obs_tuple, _ in self.obs_list:
                d = sum(a != b for a, b in zip(arch, obs_tuple))
                min_dist = min(min_dist, d)
            score += min_dist * 3.0
            if score > best_score:
                best_score = score
                best_arch = arch

        return best_arch

    def _update_model(self, arch, val_acc):
        """Add observation to marginal model."""
        arch_tuple = tuple(arch)
        if arch_tuple in self.observed:
            return

        self.observed[arch_tuple] = val_acc
        self.obs_list.append((arch_tuple, val_acc))

        for edge in range(NUM_EDGES):
            op = arch_tuple[edge]
            self.edge_op_counts[edge, op] += 1
            self.edge_op_rewards[edge, op] += val_acc
            if val_acc > self.edge_op_max_reward[edge, op]:
                self.edge_op_max_reward[edge, op] = val_acc

    def _hill_climb(self, center_arch):
        """Hill-climb on 1-edit neighbors, evaluating unseen ones."""
        neighbors = get_neighbors(center_arch)
        unseen = [n for n in neighbors
                  if is_valid_arch(n) and tuple(n) not in self.observed]
        if not unseen:
            return None, None

        best_nbr, best_val = None, -1.0
        for nbr in unseen:
            val = self.api.query_val_accuracy(nbr)
            self._update_model(nbr, val)
            if val > best_val:
                best_val = val
                best_nbr = nbr
                if val > self.best_val_acc:
                    self.best_val_acc = val
                    self.best_arch = list(nbr)

        return best_nbr, best_val

    def _get_deterministic_best(self):
        """Get predicted-best architecture from marginal max rewards."""
        if not self.obs_list:
            return random_architecture()
        arch = [int(np.argmax(self.edge_op_max_reward[e])) for e in range(NUM_EDGES)]
        if not is_valid_arch(arch):
            # Try average reward fallback
            counts = self.edge_op_counts + 1e-6
            avg = self.edge_op_rewards / counts
            arch = [int(np.argmax(avg[e])) for e in range(NUM_EDGES)]
        return arch

    def search_step(self, epoch):
        progress = epoch / max(self.num_epochs - 1, 1)
        # Decay exploration parameters
        self.temperature = self.temperature_min + (5.0 - self.temperature_min) * np.exp(-3.0 * progress)
        self.ucb_weight = 2.0 * (1 - progress) + 0.1

        mode = "eval"

        if epoch < 20:
            # Phase 1: Broad random exploration
            arch = self._diverse_sample(n_candidates=80)

        elif epoch < 70:
            # Phase 2: Marginal model guided sampling
            if epoch % 5 == 0:
                arch = self._diverse_sample(n_candidates=40)
            else:
                arch = self._sample_from_model()
                if arch is None:
                    arch = self._diverse_sample(n_candidates=20)

        elif epoch < 340:
            # Phase 3: Balanced search + periodic hill-climb
            if epoch % 10 == 0 and self.best_arch is not None:
                self._hill_climb(self.best_arch)
                mode = "hill_climb"
                # Still return current metrics below
            if arch is None:
                arch = self._sample_from_model()
                if arch is None:
                    arch = self._diverse_sample(n_candidates=20)
        elif epoch < 450:
            # Phase 4: More exploitation
            if epoch % 5 == 0 and self.best_arch is not None:
                self._hill_climb(self.best_arch)
                mode = "refine"
            if arch is None:
                arch = self._get_deterministic_best() if self.obs_list else random_architecture()
                if tuple(arch) in self.observed or not is_valid_arch(arch):
                    arch = self._sample_from_model()
                    if arch is None:
                        arch = random_architecture()
        else:
            # Phase 5: Pure exploitation + final refinement
            if epoch >= 485 and self.best_arch is not None:
                self._hill_climb(self.best_arch)
                mode = "final_refine"
            if arch is None:
                arch = self._get_deterministic_best() if self.obs_list else random_architecture()
                if tuple(arch) in self.observed or not is_valid_arch(arch):
                    arch = random_architecture()

        if arch is None or not is_valid_arch(arch) or tuple(arch) in self.observed:
            arch = random_architecture()
            # Try to find unevaluated
            for _ in range(20):
                if tuple(arch) not in self.observed:
                    break
                arch = random_architecture()

        # Evaluate
        val_acc = self.api.query_val_accuracy(arch)
        self._update_model(arch, val_acc)

        if val_acc > self.best_val_acc:
            self.best_val_acc = val_acc
            self.best_arch = list(arch)

        return {
            "best_val_acc": self.best_val_acc,
            "queries": self.api.query_count,
            "mode": mode,
        }

    def get_best_architecture(self):
        if self.best_arch is not None:
            return self.best_arch
        return random_architecture()

