        self.temperature = self.temperature_min + (10.0 - self.temperature_min) * np.exp(-4.0 * progress)
        self.ucb_weight = 3.0 * (1 - progress) + 0.1

        arch = None

        if epoch < 15:
            # Phase 1: Random exploration
            for _ in range(30):
                arch = random_architecture()
                if tuple(arch) not in self.observed:
                    break

        elif epoch < 60:
            # Phase 2: Start learning marginals, mix of UCB sampling + random
            if epoch % 3 == 0:
                # Diverse random sample
                for _ in range(20):
                    a = random_architecture()
                    if tuple(a) not in self.observed:
                        arch = a
                        break
            else:
                arch = self._sample_from_model()

        elif epoch < 300:
            # Phase 3: UCB-guided sampling with periodic hill-climb
            if epoch % 12 == 0 and self.best_arch is not None:
                self._hill_climb(self.best_arch)
            if arch is None:
                arch = self._sample_from_model()

        elif epoch < 460:
            # Phase 4: More exploitation, frequent hill-climb
            if epoch % 6 == 0 and self.best_arch is not None:
                self._hill_climb(self.best_arch)
