        }

    # Fallback when we get here from hill_climb paths (they returned early)
    # This should not normally happen - but safety net:
    if arch is None:
        for _ in range(50):
            arch = random_architecture()
            if tuple(arch) not in self.observed:
                break
        if arch is None or not is_valid_arch(arch) or tuple(arch) in self.observed:
            arch = random_architecture()
        val_acc = self.api.query_val_accuracy(arch)
        self._update_model(arch, val_acc)

    return {
        "best_val_acc": self.best_val_acc,
        "queries": self.api.query_count,
    }

def get_best_architecture(self):
    if self.best_arch is not None:
        return self.best_arch
    return random_architecture()
